"use client";

// dust-404 · 404lab
// Requires ./chrome.tsx and the 404lab tokens.

import { useRef, useState } from "react";
import { motion, useInView, useReducedMotion } from "motion/react";
import { Caption, Foot, Plate, Screen } from "./chrome";

/* ----------------------------------- dust ---------------------------------- */

const MOTES = Array.from({ length: 26 }, (_, i) => ({
  left: (i * 41 + 7) % 100,
  top: (i * 53 + 19) % 82,
  size: i % 7 === 0 ? 2.5 : 1 + (i % 3) * 0.5,
  delay: (i % 9) * 0.55,
  dur: 8 + (i % 6) * 2,
  drift: (i % 2 === 0 ? 1 : -1) * (4 + (i % 5) * 3),
}));

export function DustDemo() {
  const reduce = useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const inView = useInView(ref, { margin: "0px" });
  const [open, setOpen] = useState(false);

  return (
    <Screen
      ref={ref}
      onPointerEnter={() => setOpen(true)}
      onPointerLeave={() => setOpen(false)}
      onClick={() => setOpen((v) => !v)}
      className="bg-[#07080a]"
    >
      <Plate
        src="/worlds/w-dark-range.webp"
        className="brightness-[0.38] blur-[1px]"
      />
      <div className="absolute inset-0 bg-[linear-gradient(180deg,rgba(8,9,10,0.35)_0%,rgba(8,9,10,0.15)_50%,rgba(8,9,10,0.9)_100%)]" />
      <div
        aria-hidden
        className="absolute -left-[18%] -top-[30%] h-[150%] w-[70%] rotate-[18deg] bg-[linear-gradient(90deg,transparent,rgba(242,237,227,0.09),transparent)] blur-2xl"
      />

      {MOTES.map((m, i) => (
        <motion.span
          key={i}
          aria-hidden
          className="pointer-events-none absolute rounded-full bg-fg"
          style={{
            left: `${m.left}%`,
            top: `${m.top}%`,
            width: m.size,
            height: m.size,
            opacity: 0.35,
          }}
          animate={
            inView && !reduce
              ? {
                  y: [0, -14, 4, 0],
                  x: [0, m.drift, m.drift * 0.2, 0],
                  opacity: open ? [0.15, 0.7, 0.1] : [0.2, 0.5, 0.2],
                }
              : undefined
          }
          transition={{
            duration: m.dur,
            delay: m.delay,
            repeat: Infinity,
            ease: "easeInOut",
          }}
        />
      ))}

      <div className="absolute inset-0 z-10 flex flex-col items-center justify-center gap-3">
        <span
          className={`display text-[76px] leading-none text-fg transition-all duration-700 ${
            open ? "blur-[2px] opacity-60" : "blur-0 opacity-100"
          }`}
        >
          404
        </span>
        <span className="lab-mono text-[10px] text-white/60">
          the air keeps the shape
        </span>
      </div>

      <div className="pointer-events-none absolute bottom-9 left-4 lab-mono text-[9.5px] text-white/40">
        0.4 µm · still air
      </div>

      <Caption label="404 / dust" />
      <Foot method="motes · drift" />
    </Screen>
  );
}

"use client";

import Image from "next/image";
import { motion, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { ArrowUpRight, Check, Copy } from "lucide-react";

export const EASE = [0.22, 1, 0.36, 1] as const;

/* Every card shares the same framing so the grid reads as one set. */

export function Caption({
  label,
  className = "",
}: {
  label: string;
  className?: string;
}) {
  return (
    <span
      className={`pointer-events-none absolute left-4 top-3 z-20 lab-mono text-[10px] tracking-[0.02em] text-white/75 [text-shadow:0_1px_3px_rgba(8,9,10,0.6)] ${className}`}
    >
      {label}
    </span>
  );
}

export function HomeLink({ label = "back home" }: { label?: string }) {
  return (
    <span className="pointer-events-none inline-flex items-center gap-1 lab-mono text-[10px] text-white/70">
      {label}
      <ArrowUpRight className="size-3" strokeWidth={1.5} />
    </span>
  );
}

export function Foot({
  method,
  label,
}: {
  method: string;
  label?: string;
}) {
  return (
    <div className="pointer-events-none absolute inset-x-0 bottom-0 z-20 flex items-center justify-between px-4 pb-3">
      <HomeLink label={label} />
      <span className="lab-mono text-[10px] text-white/50">{method}</span>
    </div>
  );
}

const SCREEN =
  "group @container relative h-full w-full overflow-hidden bg-ink-900";

export function Screen({
  className = "",
  children,
  ...rest
}: React.ComponentProps<"div">) {
  return (
    <div {...rest} className={`${SCREEN} ${className}`}>
      {children}
    </div>
  );
}

export function ScreenButton({
  className = "",
  children,
  ...rest
}: React.ComponentProps<"button">) {
  return (
    <button
      type="button"
      {...rest}
      className={`${SCREEN} cursor-default text-left ${className}`}
    >
      {children}
    </button>
  );
}

export function Plate({
  src,
  className = "",
  sizes = "(max-width: 768px) 100vw, 33vw",
  opacity,
  position = "center",
}: {
  src: string;
  className?: string;
  sizes?: string;
  opacity?: number;
  position?: string;
}) {
  return (
    <Image
      src={src}
      alt=""
      fill
      sizes={sizes}
      className={`object-cover ${className}`}
      style={{ opacity, objectPosition: position }}
    />
  );
}

/* --------------------------------- helpers -------------------------------- */

export function useReplay() {
  const [run, setRun] = useState(0);
  return { run, replay: () => setRun((n) => n + 1) };
}

export function useStill() {
  return useReducedMotion() ?? false;
}

export const clamp = (v: number, min: number, max: number) =>
  Math.max(min, Math.min(max, v));

/* ------------------------------- install bits ------------------------------ */

export function CopyCommand({
  command,
  className = "",
}: {
  command: string;
  className?: string;
}) {
  const [done, setDone] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    [],
  );

  async function copy() {
    try {
      await navigator.clipboard.writeText(command);
      setDone(true);
      if (timer.current) clearTimeout(timer.current);
      timer.current = setTimeout(() => setDone(false), 1600);
    } catch {
      setDone(false);
    }
  }

  return (
    <button
      type="button"
      onClick={copy}
      aria-label={`Copy ${command}`}
      className={`group/copy flex w-full items-center justify-between gap-4 rounded-control border border-line bg-ink-900 px-3 py-2.5 text-left transition-colors duration-200 hover:border-line-2 active:translate-y-px ${className}`}
    >
      <code className="min-w-0 break-all lab-mono text-[10px] text-fg-2 sm:truncate lg:text-[12px]">
        <span className="mr-1.5 text-amber/80">$</span>
        {command}
      </code>
      <span
        aria-live="polite"
        className="shrink-0 text-fg-3 transition-colors duration-200 group-hover/copy:text-fg"
      >
        {done ? (
          <Check className="size-4 text-amber" strokeWidth={1.5} />
        ) : (
          <Copy className="size-4" strokeWidth={1.5} />
        )}
      </span>
    </button>
  );
}

export function Reveal({
  children,
  delay = 0,
  className = "",
}: {
  children: React.ReactNode;
  delay?: number;
  className?: string;
}) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      className={className}
      initial={reduce ? false : { opacity: 0, y: 10 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-60px" }}
      transition={{ duration: 0.55, ease: EASE, delay }}
    >
      {children}
    </motion.div>
  );
}
